# Fix count_zeros
def count_zeros(g):
    return sum(sum(row) for row in g)

print(f"Block zero counts (Top translucent):")
for name, g in [("TL", tl_top), ("TR", tr_top), ("BL", bl_top), ("BR", br_top)]:
    cz = count_zeros(g)
    print(f"  {name}: {cz} zeros")

print(f"Block zero counts (Bot translucent):")
for name, g in [("TL", tl_bot), ("TR", tr_bot), ("BL", bl_bot), ("BR", br_bot)]:
    cz = count_zeros(g)
    print(f"  {name}: {cz} zeros")

# Total check
print(f"\nTotal Top zero count (6x12 blocks): {count_zeros(tl_top)+count_zeros(tr_top)+count_zeros(bl_top)+count_zeros(br_top)}")
print(f"Total Bot zero count (6x12 blocks): {count_zeros(tl_bot)+count_zeros(tr_bot)+count_zeros(bl_bot)+count_zeros(br_bot)}")

# Now let me check for transformation relationships
# I'll check if any Bot block is a transformation of any Top block

print("\n\n=== Checking transformation relationships ===")

def find_matching_transform(target, sources):
    """Find which transform of which source matches target"""
    for src, name in sources:
        for i, (trans, tname) in enumerate([(identity, "id"), (flip_h, "H"), (flip_v, "V"), (rot180, "R180")]):
            r = trans(target)
            if r == src:
                return f"{tname}({name})"
    return None

# Check each Bot block against each Top block with each transform
def show_transform(g, t, tname):
    return t(g)

bot_block = tl_bot
print(f"\nChecking Bot TL against transformed Top blocks:")
for tname, t in [("id", identity), ("H", flip_h), ("V", flip_v), ("R180", rot180), ("R90", rot90), ("R270", rot270)]:
    result = t(br_top)
    if result == bot_block:
        print(f"  MATCH: Bot TL == {tname}(Top BR)")
    else:
        print(f"  {tname}: BR -> {count_zeros(result)} vs TL Bot -> {count_zeros(bot_block)}")

